export const buttonLinkStyles = tv({
  extend: buttonStyles,
  base: "cursor-pointer",
});

export type ButtonVariant = NonNullable<
  VariantProps<typeof buttonStyles>["variant"]
>;

"use client";

import { createContext, type ReactNode, useContext } from "react";

export type Size = "xs" | "sm" | "md" | "lg" | "xl";

const SizeContext = createContext<Size | undefined>(undefined);

export function useSize(size?: Size) {
  const inherited = useContext(SizeContext);
  return size ?? inherited;
}

export function SizeProvider({
  size,
  children,
}: {
  size: Size | undefined;
  children: ReactNode;
}) {
  return <SizeContext value={size}>{children}</SizeContext>;
}

"use client";

import { type MotionProps, motion, useReducedMotion } from "motion/react";
import {
  Button as AriaButton,
  type ButtonProps as AriaButtonProps,
  composeRenderProps,
} from "react-aria-components";
import { springLayout } from "./motion";
import { type ButtonVariant, buttonLabel, buttonStyles } from "./button-styles";
import { type Size, useSize } from "./size";

export interface ButtonProps
  extends Omit<
    AriaButtonProps,
    | "style"
    | "onAnimationStart"
    | "onAnimationEnd"
    | "onAnimationIteration"
    | "onHoverStart"
    | "onHoverEnd"
  > {
  ref?: React.Ref<HTMLButtonElement>;
  variant?: ButtonVariant;
  size?: Size;
  iconOnly?: boolean;
  static?: boolean;
  layout?: MotionProps["layout"];
}

const MotionButton = motion.create(AriaButton);

const pressStyles = "motion-safe:pressed:not-aria-expanded:scale-[0.96]";

export function Button({
  className,
  children,
  variant = "default",
  size: sizeProp,
  iconOnly = false,
  static: isStatic = false,
  layout,
  ...props
}: ButtonProps) {
  const reduceMotion = useReducedMotion();
  const size = useSize(sizeProp) ?? "md";
  return (
    <MotionButton
      data-slot="button"
      data-variant={variant}
      data-size={size}
      data-icon-only={iconOnly || undefined}
      layout={reduceMotion ? false : layout}
      transition={springLayout}
      className={composeRenderProps(className, (className) =>
        buttonStyles({
          variant,
          size,
          iconOnly,
          className: [!isStatic && pressStyles, className],
        }),
      )}
      {...props}
    >
      {composeRenderProps(children, buttonLabel)}
    </MotionButton>
  );
}

"use client";

import {
  animate,
  createGeneratorEasing,
  generateLinearEasing,
  spring,
  type Transition,
  useReducedMotion,
} from "motion/react";
import { type ReactElement, useLayoutEffect, useRef } from "react";
import { duration, easeOut, springSnappy, transitionFor } from "./motion";
import { cn } from "./utils";

const collectionItems =
  "[role=option], [role=menuitem], [role=menuitemradio], [role=menuitemcheckbox], [role=row]";

export const itemHighlightRing =
  "focus-visible:outline-1 focus-visible:outline-solid focus-visible:-outline-offset-1 focus-visible:outline-ring in-data-[item-highlight=ring]:focus-visible:outline-none forced-colors:focus-visible:outline-2 forced-colors:focus-visible:outline-solid forced-colors:focus-visible:-outline-offset-2";

const focusVisible =
  ":is([data-rac][data-focus-visible], :not([data-rac]):focus-visible)";

const fade = { duration: duration.fast, ease: easeOut } satisfies Transition;

const snap = { duration: 0 } satisfies Transition;

const curve = createGeneratorEasing(
  { bounce: springSnappy.bounce, duration: springSnappy.duration * 1000 },
  100,
  spring,
);

const glideTiming = {
  duration: curve.duration * 1000,
  easing: generateLinearEasing(curve.ease, curve.duration * 1000),
  fill: "forwards",
} satisfies KeyframeEffectOptions;

type Move = "glide" | "snap";

type Point = { x: number; y: number };

type Box = Point & { width: number; height: number; radius: string };

type Layer =
  | { kind: "hidden" }
  | { kind: "leaving" }
  | { kind: "shown"; target: HTMLElement; box: Box; ring: boolean };

type Flight = { from: Point; to: Point };

type Pointer = Point & {
  over: EventTarget | null;
  item: HTMLElement | null;
};

const translate = ({ x, y }: Point) => `translate(${x}px, ${y}px)`;

const position = (animation: Animation, { from, to }: Flight): Point => {
  const progress = curve.ease(
    Math.min(1, Number(animation.currentTime ?? 0) / glideTiming.duration),
  );
  return {
    x: from.x + (to.x - from.x) * progress,
    y: from.y + (to.y - from.y) * progress,
  };
};

export interface ItemHighlightProps {
  items?: string;
  placement?: "over" | "under";
  ring?: boolean;
  className?: string;
}

export function ItemHighlight({
  items = collectionItems,
  placement = "over",
  ring = false,
  className,
}: ItemHighlightProps) {
  const ref = useRef<HTMLSpanElement>(null);
  const reduceMotion = useReducedMotion();

  useLayoutEffect(() => {
    const layer = ref.current;
    const container = layer?.parentElement;
    if (!layer || !container) return;
    if (
      placement === "under" &&
      container.parentElement?.closest(
        ":has(> [data-slot=item-highlight][data-placement=under])",
      )
    )
      return;
    const rest = placement === "under" ? "under" : "fill";
    const sizeTransition = transitionFor(reduceMotion, springSnappy);
    const focusedItem = `:is(${items})${focusVisible}`;
    const virtualItem = `:is(${items})[data-focused]`;
    let focused: HTMLElement | null = null;
    let last: "pointer" | "focus" = "focus";
    let pointer: Pointer | null = null;
    let state: Layer = { kind: "hidden" };
    let flight: Flight | null = null;
    const glideEffect = new KeyframeEffect(layer, null, glideTiming);
    const glide = new Animation(glideEffect);

    const owned = (node: Element | null): node is HTMLElement =>
      node instanceof HTMLElement &&
      node.closest("[data-item-highlight], [data-empty]") === container &&
      !container.hasAttribute("data-empty");
    const itemAt = (node: Element, previous: HTMLElement | null) => {
      const item = node.closest(items);
      if (!item) return node.querySelector(items) ? previous : null;
      return owned(item) &&
        !item.matches("[data-disabled], [aria-disabled=true]")
        ? item
        : null;
    };
    const live = (item?: HTMLElement | null) =>
      item && container.contains(item) ? item : null;

    const measure = (target: HTMLElement, origin: Element, radius: string) => {
      let x = 0;
      let y = 0;
      for (let node: HTMLElement | null = target; node && node !== origin; ) {
        x += node.offsetLeft;
        y += node.offsetTop;
        node = node.offsetParent as HTMLElement | null;
        if (node && node !== origin) {
          x += node.clientLeft;
          y += node.clientTop;
        }
      }
      return {
        x,
        y,
        width: target.offsetWidth,
        height: target.offsetHeight,
        radius,
      };
    };

    const slide = (to: Point, from: Point | null, move: Move) => {
      if (from && to.x === from.x && to.y === from.y) return;
      const start = from && (flight ? position(glide, flight) : from);
      if (!start || move === "snap" || reduceMotion) {
        glide.cancel();
        flight = null;
        layer.style.transform = translate(to);
        return;
      }
      glideEffect.setKeyframes({
        transform: [translate(start), translate(to)],
      });
      glide.currentTime = 0;
      glide.play();
      flight = { from: start, to };
    };

    const place = (box: Box, from: Box | null, move: Move) => {
      slide(box, from, move);
      if (!from || box.width !== from.width || box.height !== from.height)
        animate(
          layer,
          { width: box.width, height: box.height },
          from && move === "glide" ? sizeTransition : snap,
        );
      if (!from || box.radius !== from.radius)
        animate(layer, { borderRadius: box.radius }, snap);
    };

    const paintRing = (on: boolean) => {
      if (on === (state.kind === "shown" && state.ring)) return;
      layer.toggleAttribute("data-ring", on);
      container.setAttribute("data-item-highlight", on ? "ring" : rest);
    };

    const resize = new ResizeObserver((entries) => {
      const unchanged = entries.every(
        ({ target, borderBoxSize: [size] }) =>
          state.kind === "shown" &&
          target === state.target &&
          Math.round(size.inlineSize) === state.box.width &&
          Math.round(size.blockSize) === state.box.height,
      );
      if (!unchanged) render("glide");
    });

    const hide = () => {
      if (state.kind !== "shown") return;
      paintRing(false);
      resize.unobserve(state.target);
      const leaving: Layer = { kind: "leaving" };
      state = leaving;
      animate(layer, { opacity: 0 }, fade).then(() => {
        if (state !== leaving) return;
        state = { kind: "hidden" };
        animate(layer, { width: 0, height: 0 }, snap);
      });
    };

    const render = (move: Move) => {
      const origin = layer.offsetParent;
      const target =
        origin &&
        (last === "pointer"
          ? (live(pointer?.item) ?? live(focused))
          : (live(focused) ?? live(pointer?.item)));
      if (!target) return hide();
      const kept =
        state.kind === "shown" && state.target === target ? state : null;
      const same = kept !== null;
      const box = measure(
        target,
        origin,
        kept?.box.radius ?? getComputedStyle(target).borderRadius,
      );
      place(
        box,
        state.kind === "shown" ? state.box : null,
        same ? "snap" : move,
      );
      if (state.kind !== "shown") animate(layer, { opacity: 1 }, fade);
      if (!same) {
        if (state.kind === "shown") resize.unobserve(state.target);
        resize.observe(target);
      }
      const onTarget =
        ring && target === focused && target.matches(focusVisible);
      paintRing(onTarget);
      state = { kind: "shown", target, box, ring: onTarget };
    };

    const first = (selector: string) => {
      for (const node of container.querySelectorAll(selector))
        if (owned(node)) return node;
      return null;
    };
    const syncFocus = () => {
      const next =
        first(focusedItem) ??
        (container.contains(document.activeElement)
          ? null
          : first(virtualItem));
      if (next !== focused) {
        focused = next;
        last = "focus";
      }
      render("glide");
    };
    const onPointerMove = (event: PointerEvent) => {
      if (event.pointerType === "touch") return;
      if (pointer?.over === event.target && last === "pointer") {
        pointer.x = event.clientX;
        pointer.y = event.clientY;
        return;
      }
      pointer = {
        x: event.clientX,
        y: event.clientY,
        over: event.target,
        item:
          event.target instanceof Element
            ? itemAt(event.target, pointer?.item ?? null)
            : null,
      };
      last = "pointer";
      render("glide");
    };
    const onPointerLeave = (event: PointerEvent) => {
      if (event.pointerType === "touch") return;
      pointer = null;
      render("glide");
    };
    const onScroll = () => {
      if (!pointer) return;
      const over = document.elementFromPoint(pointer.x, pointer.y);
      if (over === pointer.over) return;
      const item =
        over && container.contains(over) ? itemAt(over, pointer.item) : null;
      const moved = item !== pointer.item;
      pointer = { ...pointer, over, item };
      if (moved) render("snap");
    };

    const mutations = new MutationObserver(syncFocus);
    container.setAttribute("data-item-highlight", rest);
    mutations.observe(container, {
      subtree: true,
      childList: true,
      attributeFilter: ["data-focus-visible", "data-focused"],
    });
    resize.observe(container);
    container.addEventListener("pointermove", onPointerMove);
    container.addEventListener("pointerleave", onPointerLeave);
    container.addEventListener("focusin", syncFocus);
    container.addEventListener("focusout", syncFocus);
    document.addEventListener("scroll", onScroll, {
      capture: true,
      passive: true,
    });
    syncFocus();
    return () => {
      mutations.disconnect();
      resize.disconnect();
      container.removeEventListener("pointermove", onPointerMove);
      container.removeEventListener("pointerleave", onPointerLeave);
      container.removeEventListener("focusin", syncFocus);
      container.removeEventListener("focusout", syncFocus);
      document.removeEventListener("scroll", onScroll, { capture: true });
      container.removeAttribute("data-item-highlight");
      layer.removeAttribute("data-ring");
      glide.cancel();
      animate(layer, { opacity: 0, width: 0, height: 0 }, snap);
    };
  }, [items, placement, ring, reduceMotion]);

  return (
    <span
      ref={ref}
      aria-hidden="true"
      data-slot="item-highlight"
      data-placement={placement}
      className={cn(
        "pointer-events-none absolute top-0 left-0 bg-highlight opacity-0 forced-colors:hidden data-ring:outline-1 data-ring:outline-solid data-ring:-outline-offset-1 data-ring:outline-[color-mix(in_oklab,var(--ring),var(--foreground)_20%)]",
        placement === "over" ? "z-10" : "-z-10",
        className,
      )}
    />
  );
}

type DivRender<T> = (
  props: React.JSX.IntrinsicElements["div"],
  renderProps: T,
) => ReactElement;

export function withItemHighlight<T>(
  render: DivRender<T> | undefined,
  highlight?: ItemHighlightProps,
): DivRender<T> {
  return (props, renderProps) => {
    const next = {
      ...props,
      className: cn("relative isolate", props.className),
      children: (
        <>
          <ItemHighlight {...highlight} />
          {props.children}
        </>
      ),
    };
    return render ? render(next, renderProps) : <div {...next} />;
  };
}

"use client";

import { CaretLeftIcon, CaretRightIcon } from "@phosphor-icons/react";
import {
  Calendar as AriaCalendar,
  CalendarCell,
  CalendarGrid,
  CalendarGridBody,
  CalendarGridHeader,
  CalendarHeaderCell,
  CalendarHeading,
  type CalendarProps,
  composeRenderProps,
  type DateValue,
} from "react-aria-components";
import { cn } from "./utils";
import { Button } from "./button";
import { withItemHighlight } from "./item-highlight";

export const calendarStyles = "w-77 max-w-full text-foreground";
export const calendarGridStyles =
  "w-full table-fixed border-separate border-spacing-0 text-center";
export const calendarCells =
  "[role=gridcell] > [role=button]:not([data-unavailable])";

export const calendarHeaderCellStyles =
  "pb-1 text-xs font-medium text-muted-foreground";

export const calendarCellBaseClass =
  "relative grid aspect-square w-full cursor-pointer place-items-center text-sm tabular-nums outline-none transition-colors duration-150 ease-out-quint data-today:after:absolute data-today:after:bottom-1 data-today:after:size-1 data-today:after:rounded-full data-today:after:bg-primary selected:data-today:after:bg-current outside-month:text-muted-foreground/50 unavailable:cursor-not-allowed unavailable:text-muted-foreground unavailable:line-through disabled:cursor-default disabled:text-muted-foreground/50 focus-visible:outline-2 focus-visible:outline-solid focus-visible:z-10 focus-visible:outline-offset-2 focus-visible:outline-ring forced-colors:border-2 forced-colors:border-[Canvas] forced-colors:data-today:after:bg-[CanvasText] forced-colors:outside-month:text-[GrayText] forced-colors:disabled:text-[GrayText]";

export const calendarCellClass = `${calendarCellBaseClass} rounded-md selected:bg-primary selected:text-primary-foreground invalid:selected:bg-destructive invalid:selected:text-destructive-foreground forced-colors:selected:border-[Highlight]`;

export function Calendar<T extends DateValue>({
  className,
  children,
  render,
  ...props
}: CalendarProps<T> & React.RefAttributes<HTMLDivElement>) {
  return (
    <AriaCalendar
      {...props}
      data-slot="calendar"
      render={withItemHighlight(render, { items: calendarCells })}
      className={composeRenderProps(className, (className) =>
        cn(calendarStyles, className),
      )}
    >
      {children ?? (
        <>
          <CalendarHeader />
          <CalendarGrid className={calendarGridStyles} weekdayStyle="short">
            <CalendarGridHeader>
              {(day) => (
                <CalendarHeaderCell className={calendarHeaderCellStyles}>
                  {day}
                </CalendarHeaderCell>
              )}
            </CalendarGridHeader>
            <CalendarGridBody>
              {(date) => (
                <CalendarCell date={date} className={calendarCellClass} />
              )}
            </CalendarGridBody>
          </CalendarGrid>
        </>
      )}
    </AriaCalendar>
  );
}

export function CalendarHeader() {
  return (
    <div
      data-slot="calendar-header"
      className="mb-3 flex items-center justify-between gap-2"
    >
      <Button
        slot="previous"
        aria-label="Previous month"
        variant="ghost"
        iconOnly
      >
        <CaretLeftIcon aria-hidden="true" />
      </Button>
      <CalendarHeading className="min-w-0 text-center text-sm font-semibold [overflow-wrap:anywhere] [text-wrap:balance]" />
      <Button slot="next" aria-label="Next month" variant="ghost" iconOnly>
        <CaretRightIcon aria-hidden="true" />
      </Button>
    </div>
  );
}

"use client";

import {
  DateSegment as AriaDateSegment,
  composeRenderProps,
  type DateSegmentProps,
} from "react-aria-components";
import { cn } from "./utils";

const literalSpace = /[   ]/g;

export function DateSegment({
  className,
  children,
  ...props
}: DateSegmentProps) {
  return (
    <AriaDateSegment
      {...props}
      data-slot="date-segment"
      className={composeRenderProps(className, (className) =>
        cn(
          "rounded-sm px-0.5 py-0.5 tabular-nums outline-none caret-transparent transition-colors duration-150 ease-out-quint data-[placeholder]:text-muted-foreground [&:focus]:duration-0 invalid:text-destructive [&[data-type=literal]]:px-0 [&:focus]:bg-primary [&:focus]:text-primary-foreground forced-colors:[&:focus]:bg-[Highlight] forced-colors:[&:focus]:text-[HighlightText] forced-colors:[&:focus]:forced-color-adjust-none",
          className,
        ),
      )}
    >
      {children ??
        (({ text, type }) =>
          type === "literal" ? text.replace(literalSpace, " ") : text)}
    </AriaDateSegment>
  );
}

import type { Size } from "./size";

export const fieldSizeStyles = {
  xs: "[--field-h:1.75rem] [--field-px:0.5rem] [--field-radius:var(--radius-sm)] [--field-text:0.75rem] [--field-icon:0.875rem]",
